$total=acp_count($pdo,'SELECT COUNT(*) FROM bookings');$new=acp_count($pdo,"SELECT COUNT(*) FROM bookings WHERE status IN ('new','contacted')");$confirmed=acp_count($pdo,"SELECT COUNT(*) FROM bookings WHERE status='confirmed'");$completed=acp_count($pdo,"SELECT COUNT(*) FROM bookings WHERE status='completed'");$clients=acp_count($pdo,'SELECT COUNT(*) FROM clients');$users=acp_count($pdo,'SELECT COUNT(*) FROM users');$galleries=acp_count($pdo,'SELECT COUNT(*) FROM client_galleries');$portfolio=acp_count($pdo,'SELECT COUNT(*) FROM portfolio_items WHERE is_published=1');$reviews=acp_count($pdo,'SELECT COUNT(*) FROM reviews WHERE is_published=1');$offers=acp_count($pdo,'SELECT COUNT(*) FROM offers WHERE is_active=1 AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW())');$visitors=acp_count($pdo,"SELECT COUNT(DISTINCT visitor_key) FROM site_events WHERE created_at>=NOW()-INTERVAL 30 DAY");$today=acp_count($pdo,"SELECT COUNT(*) FROM site_events WHERE created_at>=CURDATE() AND event_type='page_view'");$recent=[];try{$recent=$pdo->query('SELECT id,name,email,service,event_date,status,created_at FROM bookings ORDER BY created_at DESC LIMIT 7')->fetchAll();}catch(Throwable $e){}$labels=[];$bookCounts=[];$viewCounts=[];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$labels[]=date('D',strtotime($d));$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE DATE(created_at)=?');$q->execute([$d]);$bookCounts[]=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM site_events WHERE event_type='page_view' AND DATE(created_at)=?");$q->execute([$d]);$viewCounts[]=(int)$q->fetchColumn();}require __DIR__.'/_layout.php';?>
